/* test_mathar_corpus.c
 *
 * Corpus runner for the integrals mined from R. J. Mathar, "Yet Another Table
 * of Integrals" (arXiv:1207.5845): tests/MatharDefiniteIntegralsCorpus.m and
 * tests/MatharIndefiniteIntegralsCorpus.m (generated by tools/mathar/).
 *
 * Record shape (one per paper entry):
 *
 *   {id, kind, Hold[symbolic], Hold[instance], {inst1, inst2, ...},
 *    {ref1, ref2, ...}, Hold[integrand], var}
 *
 *   id        "M<texline>" -- the TeX line of the entry in mathar.tex
 *   kind      "definite" | "indefinite"
 *   symbolic  Integrate[f, spec, Assumptions -> ...] with symbolic parameters
 *   instance  the same integral with the parameters replaced by inst1
 *   inst_k    parameter instantiations ({} when there are no parameters)
 *   ref_k     definite only: the value at inst_k, from the Mathematica oracle
 *             (tools/mathar/verify.wls checked it against NIntegrate)
 *
 * Every record is run in two MODES, each in its own forked child with a
 * per-case timeout:
 *   S  the symbolic integral, checked at every instantiation;
 *   N  the numeric instance, checked at inst1.
 * Checks:
 *   definite    |r/.inst - ref| / max(1, |ref|) < 1e-6
 *   indefinite  |D[r,x] - f| / max(1, |f|) < 1e-6 at x = 31/100, 77/100, 143/100
 * ConditionalExpression wrappers are stripped before the check.
 *
 * Outcomes: CORRECT, WRONG (finite value that disagrees), NONNUMERIC (closed
 * form returned but it does not numericize -- reported, counted as a failure),
 * UNEVALUATED (an Integrate head survives), TIMEOUT, CRASH.
 *
 * Gates (nonzero exit): WRONG, NONNUMERIC and CRASH must be 0 (a crash on a
 * KNOWN_CRASH id is reported but tracked separately), and CORRECT per mode must
 * not fall below its ratcheting floor.
 *
 * Environment:
 *   MATHAR_JOBS=n          parallel children (default 8)
 *   MATHAR_TIMEOUT=s       per-case timeout (default 30)
 *   MATHAR_ONLY=id,id,...  run a subset (gates are skipped)
 *   MATHAR_MODES=SN        which modes to run (default both; gates skipped
 *                          unless both run)
 *   MATHAR_CORPUS_JSON=f   append one JSON line per (record, mode) to f
 *
 * Usage: mathar_corpus_tests <corpus.m> <correct_floor_S> <correct_floor_N>
 */

#include "test_utils.h"
#include "expr.h"

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <time.h>

void symtab_init(void);
void core_init(void);

extern char* expr_to_string(struct Expr*);

enum {
    MC_CORRECT     = 'Z',
    MC_WRONG       = 'D',
    MC_NONNUMERIC  = 'X',
    MC_UNEVALUATED = 'U',
    MC_TIMEOUT     = 'T',
    MC_CRASH       = 'C',
    MC_KNOWN_CRASH = 'K',
};

#define MC_MAX_RESULT 600

/* Known kernel crashes, tracked rather than hidden: a CRASH on one of these ids
 * is reported as KNOWN-CRASH and does not trip the CRASH gate; a crash on any
 * other id does.  Remove an id as soon as it stops crashing.
 *
 * Empty since v0.458.  It briefly held the eight ids (M8220, M2014, M7503,
 * M6534, M7820, M8203, M7642, M8194) of one evaluator bug: a TimeConstrained
 * unwind restored a ParallelMixedSpecial Block and freed its memo Association
 * while code above the jump target still referenced it.  Fixed by parking
 * unwind-restored Block values until the next top-level statement
 * (mth_block_graveyard_flush, src/modular.c). */
static const char* const KNOWN_CRASH[] = { NULL };

static bool known_crash(const char* id) {
    for (int i = 0; KNOWN_CRASH[i]; i++) if (strcmp(KNOWN_CRASH[i], id) == 0) return true;
    return false;
}

/* Mathilda-language helpers, defined once in the parent before forking. */
static const char* MC_HELPERS[] = {
    "MatharCorpus`strip[r_] := r //. ConditionalExpression[c_, _] :> c",
    "MatharCorpus`deferr[r_, inst_, ref_] := "
    "N[Abs[(MatharCorpus`strip[r] /. inst) - ref]/Max[1, Abs[ref]]]",
    /* The sample point is MatharCorpus`pt, not p: Table binds its iterator
     * dynamically, and the G&R records name a parameter p -- f's p became the
     * sample point before /. inst could substitute it, and every record with
     * a parameter p was mismeasured (the 2.595 / 2.597 / 2.613 "WRONG"s). */
    "MatharCorpus`indeferr[r_, f_, x_, inst_] := Module[{g = D[MatharCorpus`strip[r], x]}, "
    "Max[Table[N[Abs[((g - f) /. inst) /. x -> MatharCorpus`pt]/"
    "Max[1, Abs[(f /. inst) /. x -> MatharCorpus`pt]]], "
    "{MatharCorpus`pt, {31/100, 77/100, 143/100}}]]]",
    NULL
};

static bool head_is(const Expr* e, const char* name) {
    return e && e->type == EXPR_FUNCTION && e->data.function.head
        && e->data.function.head->type == EXPR_SYMBOL
        && strcmp(e->data.function.head->data.symbol.name, name) == 0;
}

static bool contains_head(const Expr* e, const char* name) {
    if (!e || e->type != EXPR_FUNCTION) return false;
    if (head_is(e, name)) return true;
    if (contains_head(e->data.function.head, name)) return true;
    for (size_t i = 0; i < e->data.function.arg_count; i++)
        if (contains_head(e->data.function.args[i], name)) return true;
    return false;
}

/* Real value of a numeric node, or -1 when not a finite real number. */
static double real_value(const Expr* v) {
    if (!v) return -1;
    if (v->type == EXPR_REAL) return v->data.real;
    if (v->type == EXPR_INTEGER) return (double)v->data.integer;
    return -1;
}

static Expr* eval_call(const char* head, Expr** args, size_t n) {
    Expr* c = expr_new_function(expr_new_symbol(head), args, n);
    Expr* r = evaluate(c);
    expr_free(c);
    return r;
}

static Expr* release(Expr* held) {
    return eval_call("ReleaseHold", (Expr*[]){ expr_copy(held) }, 1);
}

/* The error measure of one check; returns MC_* and writes the worst error. */
static char check_one(Expr* r, const char* kind, Expr* inst, Expr* ref,
                      Expr* integrand, Expr* var, double* worst) {
    Expr* ev;
    if (strcmp(kind, "definite") == 0) {
        ev = eval_call("MatharCorpus`deferr",
            (Expr*[]){ expr_copy(r), expr_copy(inst), expr_copy(ref) }, 3);
    } else {
        ev = eval_call("MatharCorpus`indeferr",
            (Expr*[]){ expr_copy(r), expr_copy(integrand), expr_copy(var), expr_copy(inst) }, 4);
    }
    double d = real_value(ev);
    expr_free(ev);
    if (d < 0 || d != d) return MC_NONNUMERIC;
    if (d > *worst) *worst = d;
    return d < 1e-6 ? MC_CORRECT : MC_WRONG;
}

/* Child body: evaluate one (record, mode) and write "<code><result text>". */
static void run_case(Expr* rec, char mode, int fd, int timeout) {
    alarm((unsigned)timeout);
    const char* kind = rec->data.function.args[1]->data.string;
    Expr* held = rec->data.function.args[mode == 'S' ? 2 : 3];
    Expr* insts = rec->data.function.args[4];
    Expr* refs = rec->data.function.args[5];
    Expr* integrand_h = rec->data.function.args[6];
    Expr* var = rec->data.function.args[7];

    Expr* r = release(held);
    char code;
    if (!r || contains_head(r, "Integrate")) {
        code = MC_UNEVALUATED;
    } else {
        Expr* integrand = release(integrand_h);
        size_t ninst = insts->data.function.arg_count;
        size_t use = (mode == 'S') ? ninst : (ninst ? 1 : 0);
        double worst = 0;
        code = MC_CORRECT;
        Expr* empty = expr_new_function(expr_new_symbol("List"), NULL, 0);
        if (use == 0) {
            Expr* ref = (refs->data.function.arg_count > 0) ? refs->data.function.args[0] : empty;
            code = check_one(r, kind, empty, ref, integrand, var, &worst);
        }
        for (size_t k = 0; k < use && code == MC_CORRECT; k++) {
            Expr* inst = insts->data.function.args[k];
            Expr* ref = (k < refs->data.function.arg_count) ? refs->data.function.args[k] : empty;
            /* The instance integral already has inst1 substituted. */
            code = check_one(r, kind, inst, ref, integrand, var, &worst);
        }
        expr_free(empty);
        expr_free(integrand);
    }
    alarm(0);
    char buf[MC_MAX_RESULT + 2];
    buf[0] = code;
    char* s = r ? expr_to_string(r) : NULL;
    snprintf(buf + 1, MC_MAX_RESULT, "%s", s ? s : "");
    free(s);
    size_t len = strlen(buf);
    ssize_t w = write(fd, buf, len);
    (void)w;
    close(fd);
    _exit(0);
}

static void json_str(FILE* f, const char* s) {
    fputc('"', f);
    for (; *s; s++) {
        unsigned char c = (unsigned char)*s;
        if (c == '"' || c == '\\') { fputc('\\', f); fputc(c, f); }
        else if (c < 0x20) fprintf(f, "\\u%04x", c);
        else fputc(c, f);
    }
    fputc('"', f);
}

typedef struct {
    pid_t pid;
    int fd;
    size_t rec;
    char mode;
    time_t start;
} Slot;

static bool id_selected(const char* only, const char* id) {
    if (!only) return true;
    size_t n = strlen(id);
    const char* p = only;
    while ((p = strstr(p, id)) != NULL) {
        bool lb = (p == only) || p[-1] == ',';
        bool rb = p[n] == '\0' || p[n] == ',';
        if (lb && rb) return true;
        p += n;
    }
    return false;
}

static bool record_ok(const Expr* rec) {
    if (!head_is(rec, "List") || rec->data.function.arg_count < 8) return false;
    Expr** a = rec->data.function.args;
    return a[0]->type == EXPR_STRING && a[1]->type == EXPR_STRING
        && head_is(a[4], "List") && head_is(a[5], "List");
}

int main(int argc, char** argv) {
    alarm(0);
    setvbuf(stderr, NULL, _IONBF, 0);
    const char* corpus = argc > 1 ? argv[1] : "../MatharDefiniteIntegralsCorpus.m";
    int floor_s = argc > 2 ? atoi(argv[2]) : 0;
    int floor_n = argc > 3 ? atoi(argv[3]) : 0;
    int jobs = getenv("MATHAR_JOBS") ? atoi(getenv("MATHAR_JOBS")) : 8;
    int timeout = getenv("MATHAR_TIMEOUT") ? atoi(getenv("MATHAR_TIMEOUT")) : 30;
    const char* only = getenv("MATHAR_ONLY");
    const char* modes = getenv("MATHAR_MODES") ? getenv("MATHAR_MODES") : "SN";
    const char* json_path = getenv("MATHAR_CORPUS_JSON");
    if (jobs < 1) jobs = 1;
    if (jobs > 64) jobs = 64;

    symtab_init();
    core_init();
    for (int h = 0; MC_HELPERS[h]; h++) {
        Expr* e = parse_expression(MC_HELPERS[h]);
        ASSERT(e != NULL);
        Expr* r = evaluate(e);
        expr_free(e);
        expr_free(r);
    }

    char get_buf[1024];
    snprintf(get_buf, sizeof get_buf, "Get[\"%s\"]", corpus);
    Expr* get_call = parse_expression(get_buf);
    Expr* tests = evaluate(get_call);
    expr_free(get_call);
    if (!head_is(tests, "List")) {
        fprintf(stderr, "FAIL: could not load %s as a List.\n", corpus);
        if (tests) expr_free(tests);
        return 1;
    }
    size_t n = tests->data.function.arg_count;
    fprintf(stderr, "==> Mathar corpus %s: %zu records, modes %s, %d jobs, %ds timeout\n",
            corpus, n, modes, jobs, timeout);

    /* task list: (record, mode) */
    size_t ntask = 0, cap = 2 * n + 1;
    size_t* trec = malloc(cap * sizeof *trec);
    char* tmode = malloc(cap);
    int malformed = 0;
    for (size_t i = 0; i < n; i++) {
        Expr* rec = tests->data.function.args[i];
        if (!record_ok(rec)) { malformed++; fprintf(stderr, "  MALFORMED record %zu\n", i + 1); continue; }
        if (!id_selected(only, rec->data.function.args[0]->data.string)) continue;
        for (const char* m = modes; *m; m++) {
            if (*m != 'S' && *m != 'N') continue;
            trec[ntask] = i; tmode[ntask] = *m; ntask++;
        }
    }

    FILE* jf = json_path ? fopen(json_path, "a") : NULL;
    int cnt[2][128];
    memset(cnt, 0, sizeof cnt);
    Slot* slots = calloc((size_t)jobs, sizeof *slots);
    size_t next = 0, done = 0;
    int running = 0;
    fflush(stderr);
    while (done < ntask) {
        while (running < jobs && next < ntask) {
            int pfd[2];
            if (pipe(pfd) != 0) break;
            fflush(NULL);
            pid_t pid = fork();
            if (pid == 0) {
                close(pfd[0]);
                run_case(tests->data.function.args[trec[next]], tmode[next], pfd[1], timeout);
            }
            close(pfd[1]);
            int s = 0;
            while (slots[s].pid) s++;
            slots[s] = (Slot){ pid, pfd[0], trec[next], tmode[next], time(NULL) };
            running++;
            next++;
        }
        bool progressed = false;
        for (int s = 0; s < jobs; s++) {
            if (!slots[s].pid) continue;
            int status = 0;
            pid_t rr = waitpid(slots[s].pid, &status, WNOHANG);
            bool killed = false;
            if (rr == 0) {
                if (time(NULL) - slots[s].start <= timeout + 2) continue;
                kill(slots[s].pid, SIGKILL);
                waitpid(slots[s].pid, &status, 0);
                killed = true;
            }
            char buf[MC_MAX_RESULT + 4];
            ssize_t got = 0, rd;
            while (!killed && got < (ssize_t)sizeof buf - 1
                   && (rd = read(slots[s].fd, buf + got, sizeof buf - 1 - (size_t)got)) > 0)
                got += rd;
            buf[got > 0 ? got : 0] = '\0';
            close(slots[s].fd);
            char code;
            if (killed || (WIFSIGNALED(status) && WTERMSIG(status) == SIGALRM)) code = MC_TIMEOUT;
            else if (got < 1 || !WIFEXITED(status) || WEXITSTATUS(status) != 0) code = MC_CRASH;
            else code = buf[0];
            Expr* rec = tests->data.function.args[slots[s].rec];
            const char* id = rec->data.function.args[0]->data.string;
            int mi = slots[s].mode == 'S' ? 0 : 1;
            if (code == MC_CRASH && known_crash(id)) code = MC_KNOWN_CRASH;
            cnt[mi][(unsigned char)code]++;
            const char* name =
                code == MC_CORRECT ? "CORRECT" : code == MC_WRONG ? "WRONG" :
                code == MC_NONNUMERIC ? "NONNUMERIC" : code == MC_UNEVALUATED ? "UNEVALUATED" :
                code == MC_TIMEOUT ? "TIMEOUT" : code == MC_KNOWN_CRASH ? "KNOWN-CRASH" : "CRASH";
            double secs = difftime(time(NULL), slots[s].start);
            if (code != MC_CORRECT && code != MC_UNEVALUATED)
                fprintf(stderr, "  %-8s %c %-11s %.0fs  %.160s\n", id, slots[s].mode, name, secs,
                        (code == MC_WRONG || code == MC_NONNUMERIC) ? buf + 1 : "");
            if (jf) {
                fprintf(jf, "{\"id\":");
                json_str(jf, id);
                fprintf(jf, ",\"mode\":\"%c\",\"status\":\"%s\",\"secs\":%.0f,\"result\":", slots[s].mode, name, secs);
                json_str(jf, (code == MC_TIMEOUT || code == MC_CRASH || got < 1) ? "" : buf + 1);
                fprintf(jf, "}\n");
                fflush(jf);
            }
            slots[s].pid = 0;
            running--;
            done++;
            progressed = true;
        }
        if (!progressed) usleep(20000);
    }
    if (jf) fclose(jf);
    free(slots);
    free(trec);
    free(tmode);
    expr_free(tests);

    static const char* mname[2] = { "symbolic", "instance" };
    int wrong = 0, crash = 0, nonnum = 0;
    fprintf(stderr, "\n=== Mathar corpus result (%s) ===\n", corpus);
    for (int m = 0; m < 2; m++) {
        int tot = cnt[m]['Z'] + cnt[m]['D'] + cnt[m]['X'] + cnt[m]['U'] + cnt[m]['T'] + cnt[m]['C'] + cnt[m]['K'];
        if (!tot) continue;
        fprintf(stderr, "  [%s] total %d: CORRECT %d (%.1f%%), WRONG %d, NONNUMERIC %d, "
                "UNEVALUATED %d, TIMEOUT %d, CRASH %d, KNOWN-CRASH %d\n", mname[m], tot, cnt[m]['Z'],
                100.0 * cnt[m]['Z'] / tot, cnt[m]['D'], cnt[m]['X'], cnt[m]['U'],
                cnt[m]['T'], cnt[m]['C'], cnt[m]['K']);
        wrong += cnt[m]['D'];
        nonnum += cnt[m]['X'];
        crash += cnt[m]['C'];
    }
    fprintf(stderr, "  malformed records: %d\n", malformed);

    if (only || strchr(modes, 'S') == NULL || strchr(modes, 'N') == NULL) {
        fprintf(stderr, "(subset run: gates skipped)\n");
        return 0;
    }
    int rc = 0;
    const int WRONG_BASELINE = 0, CRASH_BASELINE = 0;
    if (malformed) { fprintf(stderr, "FAIL: %d malformed record(s)\n", malformed); rc = 1; }
    if (wrong > WRONG_BASELINE) {
        fprintf(stderr, "FAIL: %d WRONG answer(s) (baseline %d)\n", wrong, WRONG_BASELINE);
        rc = 1;
    }
    /* A closed form that does not numericize is not a verified answer -- the
     * leaked-tower-variable antiderivative (M13537) surfaced exactly here. */
    if (nonnum > 0) {
        fprintf(stderr, "FAIL: %d NONNUMERIC result(s) (baseline 0)\n", nonnum);
        rc = 1;
    }
    if (crash > CRASH_BASELINE) {
        fprintf(stderr, "FAIL: %d CRASH(es) (baseline %d)\n", crash, CRASH_BASELINE);
        rc = 1;
    }
    if (cnt[0]['Z'] < floor_s || cnt[1]['Z'] < floor_n) {
        fprintf(stderr, "FAIL: CORRECT below floor (symbolic %d < %d or instance %d < %d)\n",
                cnt[0]['Z'], floor_s, cnt[1]['Z'], floor_n);
        rc = 1;
    }
    return rc;
}
